With a mockable function, a real unit test looks like this (using vitest):

```js
import { describe, it, expect } from 'vitest';
import { summarize } from './summarize.js';

describe('summarize', () => {
  it('returns the text from the API response', async () => {
    const mockClient = {
      messages: { create: async () => ({ content: [{ text: 'A short summary.' }] }) }
    };
    const result = await summarize('long document text', mockClient);
    expect(result).toBe('A short summary.');
  });

  it('throws a clear error when the API call fails', async () => {
    const mockClient = {
      messages: { create: async () => { throw new Error('Rate limited'); } }
    };
    await expect(summarize('text', mockClient)).rejects.toThrow('Rate limited');
  });
});
```

Neither test makes a real API call. Both run in milliseconds and cost nothing — and they test the part of your code that's actually deterministic: does it handle the response correctly, does it propagate errors correctly.

```js
async function summarize(text, client, { verbose = false } = {}) {
  const systemPrompt = 'Summarize this document in 2 sentences.';
  if (verbose) {
    console.error('--- PROMPT SENT ---');
    console.error('System:', systemPrompt);
    console.error('Input (first 200 chars):', text.slice(0, 200));
  }
  const res = await client.messages.create({
    model: 'claude-3-haiku-20240307', max_tokens: 200,
    system: systemPrompt,
    messages: [{ role: 'user', content: text }]
  });
  if (verbose) {
    console.error('--- RAW RESPONSE ---');
    console.error(JSON.stringify(res, null, 2));
  }
  return res.content[0].text;
}
```

Run with `--verbose` any time output looks wrong. The two blocks — prompt sent, raw response — usually tell you within seconds which of the three categories the bug is in.

```js
function validateInput(text) {
  const trimmed = text.trim();
  if (trimmed.length === 0) {
    throw new Error('No input provided. Paste some text and try again.');
  }
  const wordCount = trimmed.split(/\s+/).length;
  if (wordCount > 5000) {
    throw new Error(
      `This tool handles up to 5,000 words. Yours is ${wordCount} words — try a shorter excerpt.`
    );
  }
  if (wordCount < 5) {
    throw new Error('Input is too short to summarize meaningfully.');
  }
  return trimmed;
}

// Use it before spending a single token on the API call
try {
  const validated = validateInput(rawInput);
  const result = await summarize(validated, client);
} catch (err) {
  console.error(err.message);
  process.exit(1);
}
```

Validating before the API call means you never pay for a request you know is going to produce a bad result.

```js
import cases from './eval-cases.json' assert { type: 'json' };
import { summarize } from './summarize.js';

async function runEvals() {
  let passed = 0, failed = 0;
  for (const c of cases) {
    const output = await summarize(c.input, client);
    const wordCount = output.split(/\s+/).length;
    const checks = [
      wordCount <= c.maxWords || `too long: ${wordCount} words (max ${c.maxWords})`,
      ...(c.mustContain ?? []).map(t => output.includes(t) || `missing required term: "${t}"`),
      ...(c.mustNotContain ?? []).map(t => !output.includes(t) || `contains forbidden term: "${t}"`)
    ];
    const failures = checks.filter(x => x !== true);
    if (failures.length === 0) { passed++; console.log(`PASS  ${c.id}`); }
    else { failed++; console.log(`FAIL  ${c.id}: ${failures.join(', ')}`); }
  }
  console.log(`\n${passed}/${cases.length} passed`);
  if (failed > 0) process.exit(1);
}
runEvals();
```

Run this before every prompt change ships. It won't catch subtle quality drift the way a human reviewer would, but it catches the concrete regressions — wrong length, missing required content, resurfaced old bugs — automatically, in seconds.
